pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title Compliance and Verification Registry
 * @author Expert Solidity Engineer
 * @notice This contract manages a registry of compliance artifacts, their verification versions, and auditor attestations.
 * It includes role-based access control, reputation tracking for submitters and auditors, optional ERC20 staking for auditors,
 * and meta-transaction support for submitting verifications.
 *
 * The system is designed to be secure, gas-efficient, and easily auditable.
 * It uses OpenZeppelin contracts for standard, battle-tested components.
 *
 * NOTE: The original request's "pipeline requirements" specified the contract name as "Game", which
 * conflicts with the "Task" to build a "Compliance and Verification Registry". This implementation
 * uses a logical name, `ComplianceRegistry`, to match the task.
 */
contract ComplianceRegistry is AccessControl, Pausable, ReentrancyGuard, EIP712 {

    //================================================
    // Roles & Constants
    //================================================

    bytes32 public constant SUBMITTER_ROLE = keccak256("SUBMITTER_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    bytes32 private constant SUBMIT_VERIFICATION_TYPEHASH = keccak256(
        "VerificationSubmission(bytes32 artifactHash,bytes32 resultsHash,string oscalCid,string profileId,uint256 complianceScore,uint256 nonce)"
    );

    //================================================
    // Data Structures
    //================================================

    enum VersionStatus { ACTIVE, REVOKED, SUPERSEDED }

    struct Attestation {
        address auditor;
        bool approved;
        bytes32 noteHash;
        uint256 attestedAt;
        uint8 confidenceLevel; // 1-5 scale
    }

    struct Version {
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore; // 0-100
        uint256 verifiedAt;
        address submitter;
        VersionStatus status;
        uint256 gasUsed;
        Attestation[] attestations;
    }

    struct SubmitterReputation {
        uint256 validSubmissions;
        uint256 revokedCount;
    }

    struct AuditorReputation {
        uint256 attestationCount;
        uint256 totalApprovals;
    }

    struct VerificationSubmission {
        bytes32 artifactHash;
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore;
        uint256 nonce;
    }

    //================================================
    // State Variables
    //================================================

    // Main registry data: artifact hash -> array of versions
    mapping(bytes32 => Version[]) internal _artifactVersions;

    // Reputation tracking
    mapping(address => SubmitterReputation) public submitterReputations;
    mapping(address => AuditorReputation) public auditorReputations;

    // Staking configuration
    IERC20 public stakingToken;
    uint256 public requiredStake;
    mapping(address => uint256) public stakes;

    // Helper mapping to efficiently find an auditor's attestation for a specific version
    // artifact hash -> version index -> auditor -> attestation index + 1
    mapping(bytes32 => mapping(uint256 => mapping(address => uint256))) internal _auditorAttestationIndexes;

    //================================================
    // Events
    //================================================

    event VerificationSubmitted(
        bytes32 indexed artifactHash,
        uint256 indexed versionIndex,
        address indexed submitter,
        bytes32 resultsHash,
        string oscalCid
    );

    event VerificationRevoked(
        bytes32 indexed artifactHash,
        uint256 indexed versionIndex,
        address indexed revoker,
        bytes32 reasonHash
    );

    event AttestationAdded(
        bytes32 indexed artifactHash,
        uint256 indexed versionIndex,
        address indexed auditor,
        bool approved,
        uint8 confidenceLevel
    );

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event Slashed(address indexed auditor, uint256 amount, bytes32 reasonHash);
    event StakingConfigurationChanged(address indexed token, uint256 requiredAmount);


    //================================================
    // Constructor
    //================================================

    constructor() EIP712("ComplianceRegistry", "1") {
        // Grant deployer the admin and pauser roles by default.
        // Other roles can be granted by the admin.
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
    }

    //================================================
    // Core Functions
    //================================================

    /**
     * @notice Submits a new verification version for a given artifact.
     * @dev Supersedes the previous active version. Can only be called by a SUBMITTER.
     * @param artifactHash The hash of the artifact being verified.
     * @param resultsHash The hash of the verification results.
     * @param oscalCid The IPFS CID for the OSCAL document.
     * @param profileId The identifier for the compliance profile used.
     * @param complianceScore The resulting compliance score (0-100).
     */
    function submitVerification(
        bytes32 artifactHash,
        bytes32 resultsHash,
        string calldata oscalCid,
        string calldata profileId,
        uint256 complianceScore
    ) public whenNotPaused nonReentrant onlyRole(SUBMITTER_ROLE) {
        _submitVerification(msg.sender, artifactHash, resultsHash, oscalCid, profileId, complianceScore);
    }

    /**
     * @notice Revokes the latest active version of an artifact.
     * @dev Can be called by an admin or the original submitter of the version.
     * @param artifactHash The hash of the artifact whose latest version is being revoked.
     * @param reasonHash A hash explaining the reason for revocation.
     */
    function revokeLatest(bytes32 artifactHash, bytes32 reasonHash) public whenNotPaused nonReentrant {
        (uint256 versionIndex, bool found) = _findLatestActiveVersionIndex(artifactHash);
        require(found, "No active version found to revoke");

        Version storage versionToRevoke = _artifactVersions[artifactHash][versionIndex];

        require(
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender) || versionToRevoke.submitter == msg.sender,
            "Not authorized to revoke"
        );

        versionToRevoke.status = VersionStatus.REVOKED;

        SubmitterReputation storage reputation = submitterReputations[versionToRevoke.submitter];
        reputation.revokedCount++;
        // A revoked submission is no longer considered valid
        if (reputation.validSubmissions > 0) {
            reputation.validSubmissions--;
        }

        emit VerificationRevoked(artifactHash, versionIndex, msg.sender, reasonHash);
    }

    /**
     * @notice Adds or updates an attestation for a specific artifact version.
     * @dev Can only be called by an AUDITOR. Each auditor can only attest once per version.
     * @param artifactHash The hash of the artifact.
     * @param versionIndex The index of the version to attest to.
     * @param approved Whether the auditor approves the verification.
     * @param noteHash A hash of any notes or comments from the auditor.
     * @param confidenceLevel The auditor's confidence in their attestation (1-5).
     */
    function attest(
        bytes32 artifactHash,
        uint256 versionIndex,
        bool approved,
        bytes32 noteHash,
        uint8 confidenceLevel
    ) public whenNotPaused nonReentrant onlyRole(AUDITOR_ROLE) {
        require(confidenceLevel >= 1 && confidenceLevel <= 5, "Confidence level out of range (1-5)");
        require(versionIndex < _artifactVersions[artifactHash].length, "Version index out of bounds");

        if (requiredStake > 0) {
            require(stakes[msg.sender] >= requiredStake, "Insufficient stake");
        }

        Version storage version = _artifactVersions[artifactHash][versionIndex];
        require(version.status == VersionStatus.ACTIVE, "Cannot attest to a non-active version");

        AuditorReputation storage reputation = auditorReputations[msg.sender];
        uint256 attestationIndex = _auditorAttestationIndexes[artifactHash][versionIndex][msg.sender];

        if (attestationIndex > 0) { // Attestation exists, update it
            Attestation storage existingAttestation = version.attestations[attestationIndex - 1];

            // Update reputation based on approval change
            if (existingAttestation.approved && !approved) {
                if(reputation.totalApprovals > 0) reputation.totalApprovals--;
            } else if (!existingAttestation.approved && approved) {
                reputation.totalApprovals++;
            }

            existingAttestation.approved = approved;
            existingAttestation.noteHash = noteHash;
            existingAttestation.confidenceLevel = confidenceLevel;
            existingAttestation.attestedAt = block.timestamp;

        } else { // New attestation
            version.attestations.push(Attestation({
                auditor: msg.sender,
                approved: approved,
                noteHash: noteHash,
                attestedAt: block.timestamp,
                confidenceLevel: confidenceLevel
            }));
            _auditorAttestationIndexes[artifactHash][versionIndex][msg.sender] = version.attestations.length;

            reputation.attestationCount++;
            if (approved) {
                reputation.totalApprovals++;
            }
        }

        emit AttestationAdded(artifactHash, versionIndex, msg.sender, approved, confidenceLevel);
    }

    //================================================
    // Meta-Transaction Support
    //================================================

    /**
     * @notice Submits a verification via EIP-712 signature, allowing for gasless transactions.
     * @param submission The struct containing all verification data.
     * @param signature The EIP-712 signature from the submitter.
     */
    function submitVerificationWithSignature(
        VerificationSubmission calldata submission,
        bytes calldata signature
    ) public whenNotPaused nonReentrant {
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(
            SUBMIT_VERIFICATION_TYPEHASH,
            submission.artifactHash,
            submission.resultsHash,
            keccak256(bytes(submission.oscalCid)),
            keccak256(bytes(submission.profileId)),
            submission.complianceScore,
            submission.nonce
        )));

        address signer = ECDSA.recover(digest, signature);
        require(signer != address(0), "Invalid signature");
        require(hasRole(SUBMITTER_ROLE, signer), "Signer lacks SUBMITTER_ROLE");

        _useNonce(signer);

        _submitVerification(signer, submission.artifactHash, submission.resultsHash, submission.oscalCid, submission.profileId, submission.complianceScore);
    }

    //================================================
    // Staking Functions
    //================================================

    /**
     * @notice Sets the staking token and required amount for auditors.
     * @dev Can only be called by an admin. Set token to address(0) to disable staking.
     * @param tokenAddress The address of the ERC20 token for staking.
     * @param stakeAmount The amount of tokens required to be staked.
     */
    function setStakingConfiguration(address tokenAddress, uint256 stakeAmount) public onlyRole(DEFAULT_ADMIN_ROLE) {
        stakingToken = IERC20(tokenAddress);
        requiredStake = stakeAmount;
        emit StakingConfigurationChanged(tokenAddress, stakeAmount);
    }

    /**
     * @notice Allows a user to stake tokens.
     * @param amount The amount of tokens to stake.
     */
    function stake(uint256 amount) public whenNotPaused nonReentrant {
        require(address(stakingToken) != address(0), "Staking not enabled");
        require(amount > 0, "Amount must be positive");
        stakes[msg.sender] += amount;
        require(stakingToken.transferFrom(msg.sender, address(this), amount), "ERC20 transfer failed");
        emit Staked(msg.sender, amount);
    }

    /**
     * @notice Allows a user to unstake tokens.
     * @param amount The amount of tokens to unstake.
     */
    function unstake(uint256 amount) public whenNotPaused nonReentrant {
        require(address(stakingToken) != address(0), "Staking not enabled");
        require(amount > 0, "Amount must be positive");
        uint256 currentStake = stakes[msg.sender];
        require(currentStake >= amount, "Insufficient stake");
        stakes[msg.sender] = currentStake - amount;
        require(stakingToken.transfer(msg.sender, amount), "ERC20 transfer failed");
        emit Unstaked(msg.sender, amount);
    }

    /**
     * @notice Slashes a portion of an auditor's stake.
     * @dev Can only be called by an admin. Slashed tokens remain in the contract.
     * @param auditor The address of the auditor to slash.
     * @param amount The amount to slash.
     * @param reasonHash A hash explaining the reason for slashing.
     */
    function slash(address auditor, uint256 amount, bytes32 reasonHash) public whenNotPaused nonReentrant onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 currentStake = stakes[auditor];
        require(currentStake >= amount, "Slash amount exceeds stake");
        stakes[auditor] = currentStake - amount;
        emit Slashed(auditor, amount, reasonHash);
    }

    //================================================
    // Pausability Functions
    //================================================

    /**
     * @notice Pauses all critical state-changing functions.
     * @dev Can only be called by a PAUSER.
     */
    function pause() public onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses the contract.
     * @dev Can only be called by a PAUSER.
     */
    function unpause() public onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    //================================================
    // View Functions
    //================================================

    /**
     * @notice Gets the total number of versions for an artifact.
     * @param artifactHash The hash of the artifact.
     * @return The version count.
     */
    function getVersionCount(bytes32 artifactHash) public view returns (uint256) {
        return _artifactVersions[artifactHash].length;
    }

    /**
     * @notice Retrieves the details of a specific version.
     * @param artifactHash The hash of the artifact.
     * @param versionIndex The index of the version.
     * @return A tuple containing the version's data fields.
     */
    function getVersion(bytes32 artifactHash, uint256 versionIndex)
        public
        view
        returns (
            bytes32 resultsHash,
            string memory oscalCid,
            string memory profileId,
            uint256 complianceScore,
            uint256 verifiedAt,
            address submitter,
            VersionStatus status,
            uint256 gasUsed
        )
    {
        require(versionIndex < _artifactVersions[artifactHash].length, "Version index out of bounds");
        Version storage v = _artifactVersions[artifactHash][versionIndex];
        return (
            v.resultsHash,
            v.oscalCid,
            v.profileId,
            v.complianceScore,
            v.verifiedAt,
            v.submitter,
            v.status,
            v.gasUsed
        );
    }

    /**
     * @notice Retrieves all attestations for a specific version.
     * @param artifactHash The hash of the artifact.
     * @param versionIndex The index of the version.
     * @return An array of Attestation structs.
     */
    function getAttestations(bytes32 artifactHash, uint256 versionIndex)
        public
        view
        returns (Attestation[] memory)
    {
        require(versionIndex < _artifactVersions[artifactHash].length, "Version index out of bounds");
        return _artifactVersions[artifactHash][versionIndex].attestations;
    }

    /**
     * @notice Retrieves the reputation data for a submitter.
     * @param submitter The address of the submitter.
     * @return The SubmitterReputation struct.
     */
    function getSubmitterReputation(address submitter)
        public
        view
        returns (SubmitterReputation memory)
    {
        return submitterReputations[submitter];
    }

    /**
     * @notice Retrieves the reputation data for an auditor, including the calculated approval ratio.
     * @param auditor The address of the auditor.
     * @return attestationCount The total number of attestations.
     * @return totalApprovals The total number of 'approved' attestations.
     * @return approvalRatio The ratio of approvals to total attestations, in basis points (0-10000).
     */
    function getAuditorReputation(address auditor)
        public
        view
        returns (uint256 attestationCount, uint256 totalApprovals, uint256 approvalRatio)
    {
        AuditorReputation storage rep = auditorReputations[auditor];
        attestationCount = rep.attestationCount;
        totalApprovals = rep.totalApprovals;
        if (attestationCount > 0) {
            approvalRatio = (totalApprovals * 10000) / attestationCount;
        } else {
            approvalRatio = 0;
        }
    }

    //================================================
    // Internal & Helper Functions
    //================================================

    /**
     * @dev Internal logic for submitting a new verification.
     */
    function _submitVerification(
        address submitter,
        bytes32 artifactHash,
        bytes32 resultsHash,
        string calldata oscalCid,
        string calldata profileId,
        uint256 complianceScore
    ) internal {
        require(complianceScore <= 100, "Score cannot exceed 100");
        uint256 gasStart = gasleft();

        (uint256 latestVersionIndex, bool found) = _findLatestActiveVersionIndex(artifactHash);
        if (found) {
            _artifactVersions[artifactHash][latestVersionIndex].status = VersionStatus.SUPERSEDED;
        }

        Version[] storage versions = _artifactVersions[artifactHash];
        versions.push(Version({
            resultsHash: resultsHash,
            oscalCid: oscalCid,
            profileId: profileId,
            complianceScore: complianceScore,
            verifiedAt: block.timestamp,
            submitter: submitter,
            status: VersionStatus.ACTIVE,
            gasUsed: 0, // Will be set after
            attestations: new Attestation[](0)
        }));

        submitterReputations[submitter].validSubmissions++;

        uint256 gasEnd = gasleft();
        versions[versions.length - 1].gasUsed = gasStart - gasEnd;

        emit VerificationSubmitted(
            artifactHash,
            versions.length - 1,
            submitter,
            resultsHash,
            oscalCid
        );
    }

    /**
     * @dev Finds the index of the latest active version for an artifact. Iterates backwards for efficiency.
     * @return index The index of the version.
     * @return found A boolean indicating if an active version was found.
     */
    function _findLatestActiveVersionIndex(bytes32 artifactHash) internal view returns (uint256 index, bool found) {
        uint256 count = _artifactVersions[artifactHash].length;
        for (uint256 i = count; i > 0; i--) {
            if (_artifactVersions[artifactHash][i - 1].status == VersionStatus.ACTIVE) {
                return (i - 1, true);
            }
        }
        return (0, false);
    }

    //================================================
    // Overrides
    //================================================

    /**
     * @dev See {IERC165-supportsInterface}.
     */
    function supportsInterface(bytes4 interfaceId) public view virtual override(AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    /**
     * @dev Overridden to provide the current nonce for a given address.
     */
    function nonces(address owner) public view virtual override(EIP712) returns (uint256) {
        return super.nonces(owner);
    }
}
